import numpy as np
from scipy import signal

def solve(problem):
    a, b = problem
    a_arr = np.asarray(a)
    b_arr = np.asarray(b)

    if a_arr.ndim != 1 or b_arr.ndim != 1:
        return signal.convolve(a_arr, b_arr, mode='full')

    na = a_arr.size
    nb = b_arr.size

    if na == 0 or nb == 0:
        return np.convolve(a_arr, b_arr, mode='full')

    if na < 8 or nb < 8:
        return np.convolve(a_arr, b_arr, mode='full')

    if na <= 64 and nb <= 64:
        return signal.convolve(a_arr, b_arr, mode='full', method='direct')

    return signal.convolve(a_arr, b_arr, mode='full', method='fft')

import numpy as np
from scipy.integrate._ivp.radau import Radau


def solve(problem):
    mu = float(problem['mu'])
    t0 = float(problem['t0'])
    t1 = float(problem['t1'])
    y0 = np.asarray(problem['y0'], dtype=float)

    def fun(t, y):
        return np.array(
            [y[1], mu * ((1.0 - y[0] * y[0]) * y[1] - y[0])],
            dtype=float
        )

    def jac(t, y):
        x = y[0]
        v = y[1]
        return np.array(
            [[0.0, 1.0],
             [-2.0 * mu * x * v - 1.0, mu * (1.0 - x * x)]],
            dtype=float
        )

    radau = Radau(fun, t0, y0, t1, rtol=1e-08, atol=1e-09, jac=jac)
    radau.step()
    while radau.status == 'running':
        radau.step()

    return radau.y.tolist()

import numpy as np
from scipy.spatial import ConvexHull

def solve(problem):
    points = problem['points']

    if isinstance(points, np.ndarray):
        if points.dtype == np.float64 and points.flags['C_CONTIGUOUS']:
            pts = points
        else:
            pts = np.ascontiguousarray(points, dtype=np.float64)
    else:
        pts = np.array(points, dtype=np.float64)

    n = pts.shape[0]
    if n >= 4:
        hull = ConvexHull(pts, qhull_options='QJ')
        vertices = hull.vertices
    else:
        vertices = np.arange(n)

    return {
        'hull_vertices': vertices.tolist(),
        'hull_points': pts[vertices].tolist()
    }

import numpy as np
import scipy.sparse

def solve(problem):
    try:
        data = np.asarray(problem['data'], dtype=np.float64)
        indices = np.asarray(problem['indices'], dtype=np.int32)
        indptr = np.asarray(problem['indptr'], dtype=np.int32)
        shape = tuple(problem['shape'])
        normed = problem['normed']
        n = shape[0]
    except Exception:
        return {'laplacian': {'data': [], 'indices': [], 'indptr': [], 'shape': problem.get('shape', (0, 0))}}

    try:
        A = scipy.sparse.csr_matrix((data, indices, indptr), shape=shape, copy=False)
        A.sum_duplicates()

        if normed:
            degrees = np.zeros(n, dtype=np.float64)
            np.add.at(degrees, A.indices, A.data)

            mask = degrees > 0
            d_inv_sqrt = np.zeros(n, dtype=np.float64)
            d_inv_sqrt[mask] = np.sqrt(1.0 / degrees[mask])

            L = scipy.sparse.diags(degrees, format='csr') - A
            D_inv_sqrt = scipy.sparse.diags(d_inv_sqrt, format='csr')
            L = D_inv_sqrt @ L @ D_inv_sqrt

            if not scipy.sparse.isspmatrix_csr(L):
                L = L.tocsr()
            L.eliminate_zeros()
        else:
            degrees = np.zeros(n, dtype=np.float64)
            np.add.at(degrees, A.indices, A.data)

            L = A.copy()
            L.data *= -1.0
            L.setdiag(degrees)
            L.eliminate_zeros()

    except Exception:
        return {'laplacian': {'data': [], 'indices': [], 'indptr': [], 'shape': shape}}

    return {'laplacian': {
        'data': L.data.tolist(),
        'indices': L.indices.tolist(),
        'indptr': L.indptr.tolist(),
        'shape': L.shape
    }}
